mod solution;

fn valid(_input: &str, actual: &str, expected: &str) -> bool { actual == expected }

fn main() {
    let cases = [
        ("edges=0-1:4,0-2:1,2-1:2,1-3:1,2-3:5","0,3,1,4"),
        ("edges=0-1:2,0-2:5,1-2:1","0,2,3"),
        ("edges=0-1:1,1-2:2,0-2:9","0,1,3"),
        ("edges=0-1:0,1-2:0","0,0,0"),
        ("edges=0-1:8,0-2:2,2-1:1,1-3:4","0,3,2,7"),
        ("  \nedges=0-1:4,0-2:1,2-1:2,1-3:1,2-3:5\n  ","0,3,1,4"),
        ("\nedges=0-1:8,0-2:2,2-1:1,1-3:4\n","0,3,2,7")
    ];
    for (i,(input,expected)) in cases.iter().enumerate() {
        let actual = solution::solve(input);
        if !valid(input,&actual,expected) { eprintln!("PRIVATE CASE {} FAILED",i+1); std::process::exit(1); }
    }
    println!("PASS dijkstra");
}
